#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail
# the project venv (CLAUDE.md), so the build works without activating it first
PY="${PY:-$HOME/.local/share/repo-qa/venv/bin/python}"
[ -x "$PY" ] || { echo "No venv at $PY. Create it (see CLAUDE.md) or set PY=/path/to/python."; exit 1; }

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────

run_wizard() {

# Run from the repo-qa folder:  bash deploy/deploy_demo.sh
# Public demo (ADR 0013): back end on Google Cloud Run (asia-east1, Taiwan; free tier), website on
# Vercel (Hobby). Non-secret values are remembered in deploy/demo.env (gitignored); the Gemini key is
# read from .env and goes only into Google Secret Manager, never into the image or a file here.
cd "$(dirname "$0")/.."
ENV_FILE=deploy/demo.env
REGION=asia-east1
SERVICE=repo-qa-demo
TOTAL_STAGES=10

banner "Deploy the repo-qa public demo"

stage "Install the Google Cloud command line (gcloud)"
if command -v gcloud >/dev/null 2>&1; then
  say "gcloud is already installed: $(gcloud --version 2>/dev/null | head -n1)"
else
  say "gcloud is Google Cloud's command line. On Arch it comes from the AUR:"
  step "In another terminal run:  yay -S google-cloud-cli"
  note "Official instructions: https://cloud.google.com/sdk/docs/install"
  pause "Press Enter once 'gcloud --version' works"
  command -v gcloud >/dev/null 2>&1 || { warn "gcloud still not found; open a new terminal and re-run"; exit 1; }
fi
pause

stage "Sign in to Google Cloud"
ACCOUNT=$(gcloud auth list --filter=status:ACTIVE --format='value(account)' 2>/dev/null || true)
if [[ -n "$ACCOUNT" ]] && ! confirm "Signed in as $ACCOUNT. Sign in as someone else?"; then
  say "Using $ACCOUNT."
else
  say "A browser opens; sign in with the Google account you want the demo under."
  gcloud auth login
fi
pause

stage "Create the project and turn on billing"
say "A new project holds the demo. Its ID must be unique across all of Google Cloud, so add a number:"
say "6 to 30 characters, lowercase letters, digits and hyphens, starting with a letter."
warn "Not a gen-lang-client-... project: those hold your Gemini key, and a card there can make the key paid."
while true; do
  ask PROJECT_ID "Project ID (e.g. repo-qa-demo-$RANDOM):"
  if [[ "$PROJECT_ID" == gen-lang-client-* ]]; then
    warn "that is your Gemini key's project; pick a new ID"
  elif gcloud projects describe "$PROJECT_ID" >/dev/null 2>&1; then
    say "Project $PROJECT_ID is yours already; using it."
    break
  elif gcloud projects create "$PROJECT_ID" --name="repo-qa demo"; then
    break
  else
    warn "could not create $PROJECT_ID (taken by someone else, or not a valid ID); try another"
  fi
done
write_env PROJECT_ID "$PROJECT_ID"
gcloud config set project "$PROJECT_ID"
say "Cloud Run needs a billing account (a card) even inside the free tier."
open_url "https://console.cloud.google.com/billing/linkedaccount?project=$PROJECT_ID"
step "Link a billing account (create one if asked; Google may offer free credit)."
pause "Press Enter once billing is linked"
until [[ "$(gcloud billing projects describe "$PROJECT_ID" --format='value(billingEnabled)' 2>/dev/null)" == "True" ]]; do
  warn "billing is not on for $PROJECT_ID yet"
  pause "Link it in the browser tab, then press Enter"
done
say "Billing is on."
pause

stage "Set a budget alert"
say "An email if the demo ever costs money. The free tier should keep it at 0."
open_url "https://console.cloud.google.com/billing/budgets?project=$PROJECT_ID"
step "Create budget → name: repo-qa demo → scope: project $PROJECT_ID"
step "Amount: specified amount, 1 (your currency) → alerts at 50%, 90%, 100% → Finish"
pause "Press Enter once the budget is saved"

stage "Turn on the Google services the demo uses"
say "Cloud Run (runs the back end), Artifact Registry (stores the image), Secret Manager (the key)."
gcloud services enable run.googleapis.com artifactregistry.googleapis.com secretmanager.googleapis.com
if ! gcloud artifacts repositories describe repo-qa --location="$REGION" >/dev/null 2>&1; then
  gcloud artifacts repositories create repo-qa --repository-format=docker --location="$REGION" \
    --description="repo-qa demo images"
fi
say "Done."
pause

stage "Store the Gemini key as a secret"
say "The key is read from .env and sent straight to Secret Manager; it is never shown or written here."
GEMINI_KEY=$(ENV_FILE=.env _existing GEMINI_API_KEY || true)
[[ -n "$GEMINI_KEY" ]] || ask_secret GEMINI_KEY "No GEMINI_API_KEY in .env; paste the key:"
if gcloud secrets describe gemini-api-key >/dev/null 2>&1; then
  printf '%s' "$GEMINI_KEY" | gcloud secrets versions add gemini-api-key --data-file=- >/dev/null
else
  printf '%s' "$GEMINI_KEY" | gcloud secrets create gemini-api-key --replication-policy=automatic --data-file=- >/dev/null
fi
unset GEMINI_KEY
NUMBER=$(gcloud projects describe "$PROJECT_ID" --format='value(projectNumber)')
gcloud secrets add-iam-policy-binding gemini-api-key \
  --member="serviceAccount:${NUMBER}-compute@developer.gserviceaccount.com" \
  --role=roles/secretmanager.secretAccessor >/dev/null
say "Secret stored; only the demo's service can read it."
pause

stage "Build and upload the back end image"
say "Copies only RAG-Anything and its index, checks for anything private, then builds (a few minutes)."
"$PY" deploy/build_demo.py --docker
IMAGE="$REGION-docker.pkg.dev/$PROJECT_ID/repo-qa/demo:latest"
nice -n 10 docker build -t "$IMAGE" deploy/build
gcloud auth configure-docker "$REGION-docker.pkg.dev" --quiet
docker push "$IMAGE"
write_env IMAGE "$IMAGE"
pause

stage "Start the back end on Cloud Run"
say "One instance at most, 512 MB, open to anyone, shut down when idle."
confirm "Make the back end public now?" || { warn "stopped before deploying"; exit 1; }
gcloud run deploy "$SERVICE" --image="$IMAGE" --region="$REGION" --allow-unauthenticated \
  --memory=512Mi --cpu=1 --max-instances=1 --timeout=120 \
  --set-secrets=GEMINI_API_KEY=gemini-api-key:latest --set-env-vars=WEB_ORIGINS=https://example.invalid
API_URL=$(gcloud run services describe "$SERVICE" --region="$REGION" --format='value(status.url)')
write_env API_URL "$API_URL"
say "Back end: $API_URL"
curl -fsS "$API_URL/health" && printf '\n' || warn "health check failed; see: gcloud run services logs read $SERVICE --region=$REGION"
pause

stage "Put the website on Vercel"
say "Uses the Vercel command line through npx (nothing installed in the project)."
step "Sign in when asked (a browser opens). Choose 'Continue with GitHub' if unsure."
npx --yes vercel@latest login
step "Next, answer: Set up? yes · scope: your account · link to existing project? no"
step "Project name: repo-qa · code directory: ./ · change settings? no"
(cd web && npx --yes vercel@latest link)
(cd web && npx --yes vercel@latest env rm NEXT_PUBLIC_API_URL production --yes >/dev/null 2>&1 || true)
(cd web && printf '%s' "$API_URL" | npx --yes vercel@latest env add NEXT_PUBLIC_API_URL production)
(cd web && npx --yes vercel@latest deploy --prod)
say "The last lines above show the address. Use the short one ending .vercel.app (Production)."
ask WEB_URL "Website address (https://...vercel.app):"
write_env WEB_URL "${WEB_URL%/}"
pause

stage "Let the website talk to the back end"
say "The back end only answers browsers on the demo's own address (CORS)."
gcloud run services update "$SERVICE" --region="$REGION" --update-env-vars="WEB_ORIGINS=$WEB_URL"
if curl -fsS -o /dev/null -D - -H "Origin: $WEB_URL" "$API_URL/health" | grep -qi "access-control-allow-origin"; then
  say "Connected."
else
  warn "the back end did not allow $WEB_URL; check the address and re-run this stage"
fi
open_url "$WEB_URL"
step "Open RAG-Anything and ask a question to check it end to end."
pause "Press Enter when done"

finish
note "Demo: $WEB_URL   Back end: $API_URL"
note "Update later: python deploy/build_demo.py --docker, then re-run stages 7 and 8 (or the whole wizard)."
}

run_wizard "$@"; exit
